import {DesktopGamepadInput} from './desktop-input.js';
import {grappleAttached} from './grapple-logic.js';
export const GRAPPLE_ICON='<svg viewBox="0 0 28 28" aria-hidden="true"><path d="M13 4v11a5 5 0 0 0 10 0v-3l-3 3M10 4h6M6 24l7-7M4 20l4 4M9 7l-4 4m0-4 4 4"/></svg>';
export function createGrappleControl({getGame,canControl=()=>true}={}){
 if(typeof document==='undefined')return{sync(){},dispose(){}};
 if(!document.getElementById('pw-grapple-style')){const style=document.createElement('style');style.id='pw-grapple-style';style.textContent=`
 #pw-grapple{position:fixed;z-index:24;right:var(--pw-right,max(16px,env(safe-area-inset-right)));bottom:calc(env(safe-area-inset-bottom) + 180px);box-sizing:border-box;display:grid;place-items:center;width:56px;height:56px;min-width:56px;min-height:56px;padding:9px;margin:0;border:1px solid var(--grapple-accent,#ff80b2);border-radius:50%;color:#eff7ff;background:linear-gradient(145deg,#def0ff24,#20354a88),#102332e8;box-shadow:inset 0 1px #ffffff40,0 3px 16px #0006;pointer-events:auto;touch-action:manipulation;user-select:none;-webkit-user-select:none}
 #pw-grapple svg{width:29px;height:29px;fill:none;stroke:var(--grapple-accent,#ff80b2);stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round;pointer-events:none}
 #pw-grapple span{position:absolute;top:-6px;right:-5px;min-width:25px;padding:4px;border-radius:10px;border:1px solid var(--grapple-accent);background:#13283bf5;font:800 9px system-ui;pointer-events:none}
 #pw-grapple kbd{position:absolute;left:-5px;bottom:-3px;padding:3px 5px;border:1px solid #ffffff55;border-radius:5px;background:#102332;font:700 9px system-ui;pointer-events:none}
 #pw-grapple[aria-pressed=true]{background:#305268;box-shadow:0 0 20px var(--grapple-accent)}#pw-grapple[data-miss=true]{border-color:#ffa76d}#pw-grapple:disabled{opacity:.45}#pw-grapple:focus-visible{outline:2px solid white;outline-offset:5px}#pw-grapple[hidden]{display:none!important}
 @media(pointer:coarse){#pw-grapple{right:calc(var(--pw-right,max(16px,env(safe-area-inset-right))) + 80px);bottom:calc(var(--pw-stick-bottom,max(28px,env(safe-area-inset-bottom))) + 231px)}#pw-grapple kbd{display:none}}
 @media(pointer:coarse) and (orientation:landscape) and (max-height:540px){#pw-grapple{right:calc(var(--pw-right,max(16px,env(safe-area-inset-right))) + 67px);bottom:calc(var(--pw-stick-bottom,max(25px,env(safe-area-inset-bottom))) + 190px);width:48px;height:48px;min-width:48px;min-height:48px}}
 body.xr-mode #pw-grapple,body.in-xr #pw-grapple,body.stereo-mode #pw-grapple{display:none!important}`;document.head.append(style);}
 const button=document.createElement('button');button.id='pw-grapple';button.type='button';button.hidden=true;button.innerHTML=GRAPPLE_ICON+'<span aria-hidden="true">20 m</span><kbd aria-hidden="true">T</kbd>';document.body.append(button);
 const pads=new DesktopGamepadInput();let lastPad=null,down=false,frame=0,disposed=false;
 const active=()=>{const g=getGame?.(),hud=document.querySelector('.pw-hud');return !!(g?.grappleEnabled&&g.state==='playing'&&g.player.hp>0&&canControl()&&!document.hidden&&(!document.hasFocus||document.hasFocus())&&!document.querySelector('dialog[open]')&&!hud?.hidden&&!hud?.classList.contains('pw-gear-open')&&!document.body.matches('.xr-mode,.in-xr'));};
 const toggle=()=>{if(active())getGame().toggleGrapple();sync();};
 const key=e=>{if(e.code!=='KeyT'||e.repeat||e.ctrlKey||e.metaKey||e.altKey||/^(INPUT|TEXTAREA|SELECT)$/.test(e.target?.tagName)||e.target?.isContentEditable)return;if(active()){e.preventDefault();toggle();}};
 // Safari may omit click for a second finger while the firing thumb is held.
 button.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();e.stopPropagation();toggle();button.blur();});button.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();if(e.detail===0)toggle();});window.addEventListener('keydown',key);
 function sync(){const g=getGame?.(),hud=document.querySelector('.pw-hud');if(hud&&button.parentNode!==hud)hud.append(button);button.hidden=!active();if(!g)return;const attached=grappleAttached(g.grapple),cooldown=Math.max(0,(g.grapple?.readyAt||0)-g.time);button.disabled=!attached&&(cooldown>0||g.grapple?.phase==='glide');button.setAttribute('aria-pressed',String(attached));button.style.setProperty('--grapple-accent',g.characterId==='lylu'?'#79bbff':'#ff80b2');button.dataset.miss=String(g.time-(g.grapple?.errorAt??-100)<1);const label=attached?'Décrocher le grappin · Saut pour une impulsion aérienne':button.dataset.miss==='true'?g.grapple.lastError:button.disabled?'Grappin en réarmement':'Lancer le grappin · viser un mur à moins de 20 m';button.setAttribute('aria-label',label);button.title=label+' · T · Manette : croix directionnelle ←';button.querySelector('span').textContent=attached?'SAUT':cooldown>0?cooldown.toFixed(1)+' s':'20 m';}
 function poll(){if(disposed)return;const pad=pads.select(navigator.getGamepads?.()||[],{focused:active()});if(pads.activeKey!==lastPad){lastPad=pads.activeKey;down=false;}const next=!!pad?.buttons[14]?.pressed;if(next&&!down&&active())toggle();down=next;sync();frame=requestAnimationFrame(poll);}frame=requestAnimationFrame(poll);
 return{button,sync,dispose(){disposed=true;cancelAnimationFrame(frame);window.removeEventListener('keydown',key);button.remove();pads.reset();}};
}
